<?php

declare(strict_types=1);

use PortLibs\Pandoc\AstNode;
use PortLibs\Pandoc\DeflateStream;
use PortLibs\Pandoc\GzipStream;
use PortLibs\Pandoc\MarkdownReader;
use PortLibs\Pandoc\PdfEngineHandoff;

$document = static function (): AstNode {
    $parsed = (new MarkdownReader())->read('Reviewer formula $E = mc^2$ keeps raw source \cite{packet}.');

    return new AstNode('document', [
        'meta' => [
            'title' => 'PDF Handoff Packet',
            'author' => ['Migration Desk', 'Content Reviewer'],
            'date' => '2026-06-04',
        ],
    ], $parsed->children);
};

return [
    'plans latex pdf engine handoff without executing a tex engine' => static function (TestRunner $t) use ($document): void {
        $handoff = new PdfEngineHandoff();
        $plan = $handoff->plan($document(), [
            'engine' => 'xelatex',
            'outputPath' => 'build/review-packet.pdf',
            'engineOptions' => ['-file-line-error'],
        ]);

        $t->same('pandoc-pdf-engine-handoff', $plan['kind']);
        $t->same('pdf', $plan['target']);
        $t->same(false, $plan['willExecute']);
        $t->same('xelatex', $plan['engine']);
        $t->same('latex', $plan['engineFamily']);
        $t->same('latex', $plan['intermediateFormat']);
        $t->same('build/review-packet.tex', $plan['sourceFile']);
        $t->same('build/review-packet.pdf', $plan['outputFile']);
        $t->same(['xelatex', '-halt-on-error', '-interaction=nonstopmode', '-file-line-error', 'build/review-packet.tex'], $plan['argv']);
        $t->contains('Reviewer formula $E = mc^2$ keeps raw source \\cite{packet}.', (string) $plan['sourceBytes']);
        $t->same(hash('sha256', (string) $plan['sourceBytes']), $plan['sourceSha256']);
        $t->same('PDF Handoff Packet', $plan['metadata']['title']);
        $t->same(['Migration Desk', 'Content Reviewer'], $plan['metadata']['author']);
        $t->same('2026-06-04', $plan['metadata']['date']);
        $t->contains('pdf-engine-not-executed', implode(',', $plan['diagnostics']));
        $t->contains('intermediate-source-rendered:latex', implode(',', $plan['diagnostics']));
    },

    'maps pandoc pdf engine families to bounded intermediate handoff argv' => static function (TestRunner $t) use ($document): void {
        $handoff = new PdfEngineHandoff();
        $typst = $handoff->plan($document(), [
            'engine' => '/usr/local/bin/typst',
            'outputPath' => 'pdf/review.pdf',
            'source' => '#set page(width: 8.5in, height: 11in)',
            'engineOptions' => ['--font-path=fonts'],
        ]);
        $weasy = $handoff->plan($document(), [
            'engine' => 'weasyprint',
            'outputPath' => 'review.pdf',
            'source' => '<!doctype html><title>Review</title>',
        ]);
        $prince = $handoff->plan($document(), [
            'engine' => 'prince',
            'outputPath' => 'review.pdf',
            'source' => '<!doctype html><title>Review</title>',
        ]);
        $roff = $handoff->plan($document(), [
            'engine' => 'pdfroff',
            'outputPath' => 'review.pdf',
            'source' => '.TL' . "\n" . 'Review',
        ]);
        $context = $handoff->plan($document(), [
            'engine' => 'context',
            'outputPath' => 'context/review.pdf',
        ]);

        $t->same('typst', $typst['engine']);
        $t->same('typst', $typst['intermediateFormat']);
        $t->same(['--font-path=fonts'], $typst['engineOptions']);
        $t->same(['/usr/local/bin/typst', 'compile', '--font-path=fonts', 'pdf/review.typ', 'pdf/review.pdf'], $typst['argv']);
        $t->same('html', $weasy['engineFamily']);
        $t->same('html5', $weasy['intermediateFormat']);
        $t->same(['weasyprint', 'review.html', 'review.pdf'], $weasy['argv']);
        $t->same(['prince', 'review.html', '-o', 'review.pdf'], $prince['argv']);
        $t->same('roff', $roff['engineFamily']);
        $t->same('ms', $roff['intermediateFormat']);
        $t->same(['pdfroff', '-o', 'review.pdf', 'review.ms'], $roff['argv']);
        $t->same('context', $context['intermediateFormat']);
        $t->same(null, $context['sourceBytes']);
        $t->contains('intermediate-writer-pending:context', implode(',', $context['diagnostics']));
    },

    'plans typst stdin source boundary provenance without staging a pseudo file' => static function (TestRunner $t) use ($document): void {
        $handoff = new PdfEngineHandoff();
        $source = '= Typst Stdin Source Packet';
        $plan = $handoff->plan($document(), [
            'engine' => 'typst',
            'sourcePath' => '-',
            'outputPath' => 'build/stdin-source.pdf',
            'source' => $source,
            'engineOptions' => [
                '--root=workspace',
                '--deps=build/stdin-source.d',
            ],
        ]);
        $pdfBytes = "%PDF-1.7\n% fake Typst stdin source packet\n%%EOF\n";
        $depfile = "build/stdin-source.pdf: - workspace/data/review.yml\n";
        $expectedSourceInput = [
            'mode' => 'stdin',
            'sourceFile' => '-',
            'path' => null,
            'stagedAsFile' => false,
            'reviewStatus' => 'review',
            'issues' => ['source-stdin-boundary'],
        ];
        $expectedReadPolicy = [
            'reviewStatus' => 'ok',
            'root' => 'workspace',
            'sourceFile' => '-',
            'inputFiles' => ['workspace/data/review.yml'],
            'insideRootFiles' => ['workspace/data/review.yml'],
            'outsideRootFiles' => [],
            'issues' => [],
        ];

        $result = $handoff->fakeRun($plan, [
            'files' => [
                'build/stdin-source.d' => $depfile,
                'build/stdin-source.pdf' => $pdfBytes,
                'workspace/data/review.yml' => "title: Review\n",
            ],
        ]);
        $sequence = $handoff->fakeRunSequence($plan, [[
            'files' => [
                'build/stdin-source.d' => $depfile,
                'build/stdin-source.pdf' => $pdfBytes,
                'workspace/data/review.yml' => "title: Review\n",
            ],
        ]]);

        $t->same('-', $plan['sourceFile']);
        $t->same(['typst', 'compile', '--root=workspace', '--deps=build/stdin-source.d', '-', 'build/stdin-source.pdf'], $plan['argv']);
        $t->same($expectedSourceInput, $plan['sourceInput']);
        $t->same('review', $plan['handoffInputProvenance']['reviewStatus']);
        $t->same($expectedSourceInput, $plan['handoffInputProvenance']['sourceInput']);
        $t->contains('source-input:review', implode(',', $plan['handoffInputProvenance']['issues']));
        $t->contains('typst-source-input:stdin', implode(',', $plan['diagnostics']));
        $t->contains('typst-source-input-issues:1', implode(',', $plan['diagnostics']));
        $t->same(true, $result['ok']);
        $t->same(hash('sha256', $source), $result['sourceSha256']);
        $t->same($expectedSourceInput, $result['sourceInput']);
        $t->same($expectedSourceInput, $result['artifactProvenanceReview']['sourceInput']);
        $t->same('ok', $result['handoffInputProvenance']['validationStatus']);
        $t->same($result['handoffInputProvenance'], $result['artifactProvenanceReview']['handoffInputProvenance']);
        $t->same($expectedReadPolicy, $result['typstReadBoundaryPolicy']);
        $t->same(['workspace/data/review.yml'], $result['engineInputFiles']);
        $t->same([], $result['engineBoundaryViolations']);
        $t->same([], $result['missingEngineInputFiles']);
        $t->same(false, array_key_exists('-', $result['producedArtifactsSha256']));
        $t->contains('staged-source-from-stdin', implode(',', $result['diagnostics']));
        $t->contains('typst-source-input-dependency-stdin', implode(',', $result['diagnostics']));
        $t->contains('typst-source-input:review', implode(',', $result['artifactProvenanceReview']['issues']));
        $t->same('review', $result['artifactProvenanceReview']['reviewStatus']);
        $t->same($expectedSourceInput, $sequence['finalSourceInput']);
        $t->same($expectedReadPolicy, $sequence['finalTypstReadBoundaryPolicy']);
    },

    'preserves typst stdin source input in boundary matrix without executing' => static function (TestRunner $t) use ($document): void {
        $handoff = new PdfEngineHandoff();
        $source = '= Typst Stdin Matrix Packet';
        $plan = $handoff->plan($document(), [
            'engine' => 'typst',
            'sourcePath' => '-',
            'outputPath' => 'build/stdin-matrix.pdf',
            'source' => $source,
        ]);
        $pdfBytes = "%PDF-1.7\n% fake Typst stdin matrix packet\n%%EOF\n";
        $expectedSourceInput = [
            'mode' => 'stdin',
            'sourceFile' => '-',
            'path' => null,
            'stagedAsFile' => false,
            'reviewStatus' => 'review',
            'issues' => ['source-stdin-boundary'],
        ];
        $expectedSourceCase = [
            'case' => 'source-input',
            'reviewStatus' => 'review',
            'observed' => 1,
            'details' => [
                'mode' => 'stdin',
                'sourceFile' => '-',
                'path' => null,
                'stagedAsFile' => false,
            ],
            'issues' => ['source-stdin-boundary'],
        ];

        $result = $handoff->fakeRun($plan, [
            'files' => [
                'build/stdin-matrix.pdf' => $pdfBytes,
            ],
        ]);
        $sequence = $handoff->fakeRunSequence($plan, [[
            'files' => [
                'build/stdin-matrix.pdf' => $pdfBytes,
            ],
        ]]);

        $t->same($expectedSourceInput, $plan['sourceInput']);
        $t->same(['source-input', 'output-format'], array_column($plan['typstBoundaryMatrix']['cases'], 'case'));
        $t->same($expectedSourceCase, $plan['typstBoundaryMatrix']['cases'][0]);
        $t->same('review', $plan['typstBoundaryMatrix']['reviewStatus']);
        $t->same(2, $plan['typstBoundaryMatrix']['caseCount']);
        $t->same(1, $plan['typstBoundaryMatrix']['reviewCaseCount']);
        $t->same(1, $plan['typstBoundaryMatrix']['issueCount']);
        $t->contains('source-input:source-stdin-boundary', implode(',', $plan['typstBoundaryMatrix']['issues']));
        $t->contains('typst-boundary-matrix-cases:2', implode(',', $plan['diagnostics']));
        $t->same(true, $result['ok']);
        $t->same($expectedSourceCase, $result['typstBoundaryMatrix']['cases'][0]);
        $t->same($result['typstBoundaryMatrix'], $result['artifactProvenanceReview']['typstBoundaryMatrix']);
        $t->contains('typst-source-input:review', implode(',', $result['artifactProvenanceReview']['issues']));
        $t->same($result['typstBoundaryMatrix'], $sequence['finalTypstBoundaryMatrix']);
    },

    'plans typst boundary option provenance without executing' => static function (TestRunner $t) use ($document): void {
        $handoff = new PdfEngineHandoff();
        $plan = $handoff->plan($document(), [
            'engine' => 'typst',
            'sourcePath' => 'workspace/build/boundary.typ',
            'outputPath' => 'build/boundary.pdf',
            'source' => '= Typst Boundary Packet',
            'engineOptions' => [
                '--root=workspace',
                '--font-path=fonts',
