                '--package-cache',
                'https://cache.example.invalid/typst',
                '--deps=build/boundary.d',
            ],
        ]);
        $pdfBytes = "%PDF-1.7\n% fake Typst boundary provenance packet\n%%EOF\n";
        $depfile = "build/boundary.pdf: workspace/build/boundary.typ\n";
        $expected = [
            'reviewStatus' => 'review',
            'root' => ['raw' => 'workspace', 'path' => 'workspace', 'kind' => 'relative', 'safe' => true, 'issues' => []],
            'fontPaths' => [
                ['raw' => 'fonts', 'path' => 'fonts', 'kind' => 'relative', 'safe' => true, 'issues' => []],
                ['raw' => 'shared fonts', 'path' => 'shared fonts', 'kind' => 'relative', 'safe' => true, 'issues' => []],
            ],
            'packagePath' => ['raw' => 'vendor/typst-packages', 'path' => 'vendor/typst-packages', 'kind' => 'relative', 'safe' => true, 'issues' => []],
            'packageCache' => ['raw' => 'https://cache.example.invalid/typst', 'path' => 'https://cache.example.invalid/typst', 'kind' => 'uri', 'safe' => false, 'issues' => ['package-cache-external-boundary']],
            'inputVariables' => [],
            'issues' => ['package-cache-external-boundary'],
            'packageStoragePolicy' => [
                'reviewStatus' => 'review',
                'storageEntryCount' => 2,
                'safeStorageEntryCount' => 1,
                'unsafeStorageEntryCount' => 1,
                'packagePathCount' => 1,
                'packageCacheCount' => 1,
                'relativeStorageEntryCount' => 1,
                'workspaceStorageEntryCount' => 0,
                'absoluteStorageEntryCount' => 0,
                'uriStorageEntryCount' => 1,
                'invalidStorageEntryCount' => 0,
                'issues' => ['package-cache-external-boundary'],
            ],
            'dependencyOutput' => [
                'file' => ['raw' => 'build/boundary.d', 'path' => 'build/boundary.d', 'kind' => 'relative', 'safe' => true, 'issues' => []],
                'format' => null,
                'issues' => [],
            ],
        ];

        $result = $handoff->fakeRun($plan, [
            'files' => [
                'build/boundary.d' => $depfile,
                'build/boundary.pdf' => $pdfBytes,
            ],
        ]);
        $sequence = $handoff->fakeRunSequence($plan, [
            [
                'files' => [
                    'build/boundary.d' => $depfile,
                    'build/boundary.pdf' => $pdfBytes,
                ],
            ],
        ]);

        $t->same($expected, $plan['typstBoundaryProvenance']);
        $t->contains('typst-boundary-provenance:review', implode(',', $plan['diagnostics']));
        $t->contains('typst-root-boundary:workspace', implode(',', $plan['diagnostics']));
        $t->contains('typst-font-paths:2', implode(',', $plan['diagnostics']));
        $t->contains('typst-package-path:vendor/typst-packages', implode(',', $plan['diagnostics']));
        $t->contains('typst-package-cache:https://cache.example.invalid/typst', implode(',', $plan['diagnostics']));
        $t->contains('typst-package-storage-policy:review', implode(',', $plan['diagnostics']));
        $t->contains('typst-package-storage-unsafe:1', implode(',', $plan['diagnostics']));
        $t->contains('typst-dependency-output:build/boundary.d', implode(',', $plan['diagnostics']));
        $t->contains('typst-boundary-issues:1', implode(',', $plan['diagnostics']));
        $t->same(true, $result['ok']);
        $t->same($expected, $result['typstBoundaryProvenance']);
        $t->same($expected, $result['artifactProvenanceReview']['typstBoundaryProvenance']);
        $t->same('review', $result['artifactProvenanceReview']['reviewStatus']);
        $t->contains('typst-boundary-provenance:review', implode(',', $result['artifactProvenanceReview']['issues']));
        $t->same($expected, $sequence['finalTypstBoundaryProvenance']);
    },

    'summarizes typst boundary provenance for package review' => static function (TestRunner $t) use ($document): void {
        $handoff = new PdfEngineHandoff();
        $plan = $handoff->plan($document(), [
            'engine' => 'typst',
            'sourcePath' => 'workspace/build/boundary-summary.typ',
            'outputPath' => 'build/boundary-summary.pdf',
            'source' => '= Typst Boundary Summary Packet',
            'engineOptions' => [
                '--root=workspace',
                '--font-path=fonts',
                '--font-path=/usr/share/fonts',
                '--cert=certs/internal.pem',
                '--cert=https://ca.example.invalid/root.pem',
                '--package-path=vendor/typst',
                '--package-cache=https://cache.example.invalid/typst',
                '--input=audience=reviewer',
                '--pages=1-2',
                '--ppi=300',
                '--pdf-standard=a-2b',
                '--features=html,packages',
