        $depfile = "build/boundary-summary.pdf: workspace/build/boundary-summary.typ\n";
        $timingsBytes = '{"traceEvents":[{"name":"export","args":{"file":"workspace/build/boundary-summary.typ","line":1}}]}';
        $expectedSummary = [
