            'endobj',
            '11 0 obj',
            '<< /Type /XObject /Subtype /Image /Width 20 /Height 20 /BitsPerComponent 8 /ColorSpace /DeviceRGB /Length ' . strlen($imageBytes) . ' >>',
            'stream',
            $imageBytes,
            'endstream',
            'endobj',
            'trailer',
            '<< /Root 1 0 R >>',
            '%%EOF',
            '',
