        $expected = [
            [
                'page' => 1,
                'pageObject' => '3 0 R',
                'resourceName' => 'FxBadge',
                'formObject' => '8 0 R',
                'inherited' => true,
                'bbox' => [0.0, 0.0, 200.0, 80.0],
                'matrix' => [1.0, 0.0, 0.0, 1.0, 12.0, 24.0],
