            ],
            [
                'page' => 2,
                'pageObject' => '4 0 R',
                'resourceName' => 'FxOverlay',
                'formObject' => '9 0 R',
                'inherited' => false,
                'bbox' => [0.0, 0.0, 100.0, 100.0],
                'matrix' => null,
                'resourcesPresent' => false,
                'groupSubtype' => 'Transparency',
                'groupColorSpace' => 'DeviceCMYK',
                'groupIsolated' => false,
                'groupKnockout' => true,
                'filters' => ['FlateDecode'],
                'streamBytes' => strlen($overlayBytes),
