            '<< /Type /XRef /Size 12 /Root 1 0 R /Index [0 12] /W [1 2 1] /Filter /FlateDecode /Length ' . strlen($xrefBytes) . ' >>',
            'stream',
            $xrefBytes,
            'endstream',
            'endobj',
            '12 0 obj',
            '<< /Type /ObjStm /N 1 /First ' . strlen($objectStreamHeader) . ' /Filter /LZWDecode /Length ' . strlen($objectStreamBytes) . ' >>',
            'stream',
