        $sequence = $handoff->fakeRunSequence($plan, [
            [
                'files' => [
                    'packets/stream-filters.pdf' => $pdfBytes,
                ],
            ],
        ]);
        $expectedStreams = [
            [
                'surface' => 'xref-stream',
                'source' => 'xref:11 0 R',
                'object' => '11 0 R',
                'filters' => ['FlateDecode'],
                'action' => 'deferred-decode',
