        $expected = [
            'streamCount' => 7,
            'filterCount' => 8,
            'filters' => [
                'ASCII85Decode' => 1,
                'Crypt' => 1,
                'DCTDecode' => 1,
                'FlateDecode' => 3,
                'JPXDecode' => 1,
                'LZWDecode' => 1,
