            '2 0 obj',
            '<< /Type /Pages /Count 1 /Kids [3 0 R] >>',
            'endobj',
            '3 0 obj',
            '<< /Type /Page /Parent 2 0 R >>',
            'endobj',
            '8 0 obj',
            '<< /BaseVersion /2.0 /ExtensionLevel 32000 >>',
            'endobj',
            'trailer',
            '<< /Root 1 0 R >>',
            '%%EOF',
            '',
        ]);

        $result = $handoff->fakeRun($plan, [
            'files' => [
                'packets/versioned.pdf' => $pdfBytes,
            ],
